let arr = ["red", "green", "blue"];

let set = new Set(["Alice", "Bob"]);

let map = new Map();
map.set("Chinese", 88);
map.set("Math", 98);
map.set("English", 59);

for(let value of arr.values()) {
    console.log(value); // red
                        // green
                        // blue
}

for(let value of set.values()) {
    console.log(value); // Alice
                        // Bob
}

for(let value of map.values()) {
    console.log(value); // 88
                        // 98
                        // 59

for (let key of arr.keys()) {
  console.log(key); // 0
                    // 1
                    // 2
}

for (let key of set.keys()) {
  console.log(key); // Alice
                    // Bob
}

for (let key of map.keys()) {
  console.log(key); // Chinese
                    // Math
                    // English
}

for (let entry of arr.entries()) {
  console.log(entry); // [ 0, 'red' ]
                      // [ 1, 'green' ]
                      // [ 2, 'blue' ]
}

for (let entry of set.entries()) {
  console.log(entry); // [ 'Alice', 'Alice' ]
                      // [ 'Bob', 'Bob' ]
}

for (let entry of map.entries()) {
  console.log(entry); // [ 'Chinese', 88 ]
                      // [ 'Math', 98 ]
                      // [ 'English', 59 ]
}

for (let item of arr) {
  console.log(item); // red
                     // green
                     // blue
}

for (let item of set) {
  console.log(item); // Alice
                     // Bob
}

for (let item of map) {
  console.log(item); // [ 'Chinese', 88 ]
                     // [ 'Math', 98 ]
                     // [ 'English', 59 ]
}
